<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { ElButton, ElCard } from 'element-plus';
import { delivery, type DeliveryActor, type DeliveryEntry, type DeliveryFilter, type DeliveryIssue, type DeliveryKind, type DeliveryPriority, type DeliveryRecord, type DeliveryRelease, type DeliveryReview, type DeliveryRole, type DeliveryStatus } from './delivery';
import './dashboard.css';
import './delivery.css';
import { mountDeliveryDialog } from './delivery-dialog';

const kinds: { id: DeliveryKind; label: string }[] = [{ id: 'requirement', label: '需求' }, { id: 'task', label: '任务' }, { id: 'issue', label: 'Issue' }, { id: 'review', label: '待审核' }];
const statuses: Record<DeliveryStatus, string> = { draft: '草案', pending: '待处理', inProgress: '进行中', blocked: '阻塞', done: '已完成', approved: '已通过', rejected: '已驳回', needsChanges: '需修改', waived: '已豁免' };
const roles: Record<DeliveryRole, string> = { contributor: '普通贡献者 / AI', productOwner: '产品负责人', techLead: '技术负责人', releaseLead: '发布负责人' };
const actorFor = (role: DeliveryRole): DeliveryActor => ({ id: role === 'techLead' ? 'tech-lead' : role === 'releaseLead' ? 'release-lead' : role === 'productOwner' ? 'product-lead' : 'ai', role });
const emptyFilter = (): Omit<DeliveryFilter, 'kind'> => ({ page: 1, pageSize: 10 });
const emptyRelease = (): Omit<DeliveryRelease, 'id' | 'kind' | 'revision' | 'updatedAt' | 'publishedAt'> => ({ title: '', status: 'draft', priority: 'P1', phase: '预览', owner: 'release-lead', requirementIds: [], description: '', acceptance: [], evidence: [], risk: '', history: [], environment: 'preview', version: '', previousVersion: '', changeSummary: '', testEvidence: [], rollbackSteps: '', knownRisks: [] });
const isIssue = (item: DeliveryEntry): item is DeliveryIssue => item.kind === 'issue';
const isReview = (item: DeliveryEntry): item is DeliveryReview => item.kind === 'review';
const isRelease = (item: DeliveryEntry): item is DeliveryRelease => item.kind === 'release';
const themeChoice = ref(localStorage.getItem('iot-atlas-theme') || 'dark');
const media = matchMedia('(prefers-color-scheme: dark)');
const systemDark = ref(media.matches);
const syncSystem = () => { systemDark.value = media.matches; };
media.addEventListener('change', syncSystem);
onBeforeUnmount(() => media.removeEventListener('change', syncSystem));
watch([themeChoice, systemDark], () => { document.documentElement.dataset.theme = themeChoice.value === 'dark' || (themeChoice.value === 'system' && systemDark.value) ? 'dark' : 'light'; localStorage.setItem('iot-atlas-theme', themeChoice.value); }, { immediate: true });
const role = ref<DeliveryRole>('contributor'), actor = computed(() => actorFor(role.value));
const filter = ref(emptyFilter()), draft = ref(emptyFilter());
const pages = ref<Record<DeliveryKind, number>>({ requirement: 1, task: 1, issue: 1, review: 1, release: 1, change: 1 });
const selectedId = ref('IOT-TENANT-001'), editor = ref<'requirement' | 'task' | 'issue' | 'release' | null>(null);
let modalTrigger: HTMLElement | null = null;
let restoreModalFocus = true;
const rememberModalTrigger = () => { modalTrigger = document.activeElement instanceof HTMLElement ? document.activeElement : null; restoreModalFocus = true; };
watch(editor, (kind, _old, onCleanup) => {
  if (!kind) return;
  const cleanup = mountDeliveryDialog(() => { editor.value = null; });
  onCleanup(() => { cleanup(); if (restoreModalFocus) requestAnimationFrame(() => modalTrigger?.isConnected && modalTrigger.focus()); restoreModalFocus = true; });
}, { flush: 'post' });
const editingRequirementId = ref<string | null>(null);
const editingReleaseId = ref<string | null>(null);
const title = ref(''), newId = ref(''), description = ref(''), owner = ref(''), requirementId = ref('IOT-TENANT-001'), priority = ref<DeliveryPriority>('P1'), severity = ref<DeliveryIssue['severity']>('medium'), acceptance = ref('');
const reviewVerdict = ref<DeliveryReview['verdict']>('needsChanges'), reviewReason = ref('');
const statusDraft = ref<DeliveryStatus>('pending'), resolution = ref('');
const releaseDraft = ref(emptyRelease()), message = ref(''), reload = ref(0);
const rollbackReason = ref(''), rollbackVerification = ref('');
const columns = computed(() => { void reload.value; return kinds.map(kind => { const result = delivery.list({ ...filter.value, kind: kind.id, page: pages.value[kind.id] }); return { ...kind, items: 'data' in result ? result.data.items : [], total: 'data' in result ? result.data.total : 0 }; }); });
const selected = computed(() => { void reload.value; const result = delivery.get(selectedId.value); return 'data' in result ? result.data : null; });
const related = computed(() => { if (!selected.value) return []; const result = delivery.trace(selected.value.id); return 'data' in result ? result.data.related : []; });
const requirements = computed(() => { void reload.value; const result = delivery.list({ kind: 'requirement', page: 1, pageSize: 100 }); return 'data' in result ? result.data.items : []; });
const releases = computed(() => { void reload.value; const result = delivery.list({ kind: 'release', page: 1, pageSize: 100 }); return 'data' in result ? result.data.items : []; });
const releaseCheck = computed(() => delivery.checkRelease(releaseDraft.value));
function releaseAction(reason: string) {
  const id = reason.match(/REVIEW-\d{3}|ISSUE-\d{8}-\d{3}|IOT-[A-Z]+-\d{3}/)?.[0];
  if (id) return { owner: id.startsWith('REVIEW') ? '指定审核人' : id.startsWith('ISSUE') ? '产品或技术负责人' : '产品负责人', target: id };
  const field = reason.includes('目标版本') ? '目标版本' : reason.includes('有效的关联需求') ? '发布关联需求' : reason.includes('变更摘要') ? '变更摘要' : reason.includes('测试证据') ? '测试证据' : reason.includes('回滚步骤') ? (releaseDraft.value.previousVersion ? '回滚步骤' : '上一已验证版本') : '';
  return { owner: '发布负责人', target: field };
}
function openReleaseAction(reason: string) {
  const { target } = releaseAction(reason);
  if (target.startsWith('REVIEW-') || target.startsWith('ISSUE-') || target.startsWith('IOT-')) { const row = delivery.get(target); if ('data' in row) { choose(row.data); restoreModalFocus = false; editor.value = null; requestAnimationFrame(() => { const detail = document.querySelector<HTMLElement>('.delivery-detail'); detail?.scrollIntoView({ block: 'start' }); detail?.focus(); }); } }
  else document.querySelector<HTMLElement>(`.delivery-modal [aria-label="${target}"]`)?.focus();
}

function show(result: { error: { message: string } } | { data: DeliveryEntry }) { if ('error' in result) { message.value = result.error.message; return; } message.value = `${result.data.id} 已保存到本端模拟记录`; selectedId.value = result.data.id; editor.value = null; reload.value++; }
function startCreate(kind: typeof editor.value) { rememberModalTrigger(); editingRequirementId.value = null; editingReleaseId.value = null; editor.value = kind; message.value = ''; title.value = ''; newId.value = ''; description.value = ''; owner.value = ''; requirementId.value = 'IOT-TENANT-001'; priority.value = 'P1'; severity.value = 'medium'; acceptance.value = ''; releaseDraft.value = emptyRelease(); }
function startEditRequirement(item: DeliveryEntry) { if (item.kind !== 'requirement') return; rememberModalTrigger(); editingRequirementId.value = item.id; editor.value = 'requirement'; message.value = ''; title.value = item.title; newId.value = item.id; description.value = item.description; owner.value = item.owner; priority.value = item.priority; acceptance.value = item.acceptance.join('\n'); }
function startEditRelease(item: DeliveryRelease) { rememberModalTrigger(); editingReleaseId.value = item.id; editingRequirementId.value = null; releaseDraft.value = JSON.parse(JSON.stringify(item)) as typeof releaseDraft.value; editor.value = 'release'; message.value = ''; }
function saveNew() {
  if (editor.value === 'task') show(delivery.createTask(actor.value, { title: title.value, requirementIds: requirementId.value ? [requirementId.value] : [], owner: owner.value, priority: priority.value, description: description.value }));
  if (editor.value === 'issue') show(delivery.createIssue(actor.value, { title: title.value, requirementIds: requirementId.value ? [requirementId.value] : [], owner: owner.value, priority: priority.value, description: description.value, severity: severity.value }));
  if (editor.value === 'requirement') {
    const input: DeliveryRecord = { id: newId.value, kind: 'requirement', title: title.value, status: 'pending', priority: priority.value, phase: '需求', owner: owner.value, requirementIds: [newId.value], description: description.value, acceptance: acceptance.value.split('\n').map(item => item.trim()).filter(Boolean), evidence: [], risk: '', updatedAt: '', revision: 0, history: [] };
    const current = editingRequirementId.value ? delivery.get(editingRequirementId.value) : null;
    if (current && 'data' in current) show(delivery.save(actor.value, { ...current.data, ...input, status: current.data.status, phase: current.data.phase, evidence: current.data.evidence, risk: current.data.risk } as DeliveryRecord, current.data.revision));
    else show(delivery.save(actor.value, input));
  }
  if (editor.value === 'release') { const current = editingReleaseId.value ? delivery.get(editingReleaseId.value) : null; if (current && 'data' in current && isRelease(current.data)) show(delivery.updateRelease(actor.value, current.data.id, JSON.parse(JSON.stringify(releaseDraft.value)), current.data.revision)); else show(delivery.createRelease(actor.value, JSON.parse(JSON.stringify(releaseDraft.value)))); }
}
function choose(item: DeliveryEntry) { selectedId.value = item.id; statusDraft.value = item.status; resolution.value = isIssue(item) ? item.resolution ?? '' : ''; message.value = ''; }
function saveStatus() { if (!selected.value || ['review', 'release'].includes(selected.value.kind)) return; const input = { ...selected.value, status: statusDraft.value, ...(isIssue(selected.value) ? { resolution: resolution.value } : {}) } as DeliveryRecord | DeliveryIssue; show(delivery.save(actor.value, input, selected.value.revision)); }
function decide() { if (selected.value && isReview(selected.value)) show(delivery.decideReview(actor.value, selected.value.id, reviewVerdict.value, reviewReason.value, selected.value.revision)); }
function publish() { if (selected.value && isRelease(selected.value)) show(delivery.publish(actor.value, selected.value.id, selected.value.revision)); }
function rollback() { if (selected.value && isRelease(selected.value)) show(delivery.rollback(actor.value, selected.value.id, rollbackReason.value, rollbackVerification.value, selected.value.revision)); }
function apply() { filter.value = { ...draft.value, page: 1 }; pages.value = { requirement: 1, task: 1, issue: 1, review: 1, release: 1, change: 1 }; }
function reset() { draft.value = emptyFilter(); filter.value = emptyFilter(); pages.value = { requirement: 1, task: 1, issue: 1, review: 1, release: 1, change: 1 }; }
</script>

<template>
<div class="atlas-dashboard atlas-delivery">
  <main class="atlas-workspace"><header class="atlas-header"><div><small>IoT Atlas / 工程治理</small><h1>交付看板</h1><p>当前数据是各端独立的本地模拟记录；审核结论与发布操作不代表仓库实际批准或部署。</p></div><div class="header-actions"><label>主题<select v-model="themeChoice" aria-label="主题"><option value="dark">暗色</option><option value="light">亮色</option><option value="system">跟随系统</option></select></label><label>模拟治理身份<select v-model="role" aria-label="模拟治理身份"><option v-for="(label,id) in roles" :key="id" :value="id">{{ label }}</option></select></label></div></header>
    <ElCard class="delivery-intro"><strong>事实来源</strong><span>需求文档、权限契约和 QUALITY 中的当前状态已映射为初始 Mock 记录。权限冲突 Issue 与待审核项保持阻塞；模拟操作只保存在当前应用浏览器。</span></ElCard>
    <ElCard class="delivery-filters"><label>搜索编号或标题<input v-model="draft.keyword" aria-label="搜索交付记录"></label><label>状态<select v-model="draft.status" aria-label="交付状态"><option value="">全部状态</option><option v-for="(label,id) in statuses" :key="id" :value="id">{{ label }}</option></select></label><label>优先级<select v-model="draft.priority" aria-label="交付优先级"><option value="">全部优先级</option><option v-for="item in ['P0','P1','P2','P3']" :key="item">{{ item }}</option></select></label><label>阶段<input v-model="draft.phase" aria-label="交付阶段"></label><label>负责人<input v-model="draft.owner" aria-label="交付负责人筛选"></label><label>关联需求<select v-model="draft.requirementId" aria-label="关联需求筛选"><option value="">全部需求</option><option v-for="item in requirements" :key="item.id">{{ item.id }}</option></select></label><ElButton type="primary" @click="apply">查询</ElButton><ElButton @click="reset">重置</ElButton></ElCard>
    <p v-if="message" class="delivery-feedback" role="status">{{ message }}</p>
    <div class="delivery-board" aria-label="交付记录概览"><ElCard v-for="column in columns" :key="column.id" class="delivery-column"><h2>{{ column.label }} <small>{{ column.total }}</small></h2><button v-for="item in column.items" :key="item.id" class="delivery-card" :class="{ selected: selectedId === item.id }" @click="choose(item)"><small>{{ item.id }} · {{ item.priority }}</small><strong>{{ item.title }}</strong><span>{{ statuses[item.status] }} · {{ item.owner }}</span><em v-if="item.risk">{{ item.risk }}</em></button><p v-if="!column.items.length">当前条件下没有记录。</p><div v-if="column.total > filter.pageSize" class="delivery-pager"><button :disabled="pages[column.id] <= 1" @click="pages[column.id]--">上一页</button><span>{{ pages[column.id] }} / {{ Math.ceil(column.total / filter.pageSize) }}</span><button :disabled="pages[column.id] * filter.pageSize >= column.total" @click="pages[column.id]++">下一页</button></div></ElCard></div>
    <div class="delivery-actions"><ElButton @click="startCreate('requirement')">新建需求草案</ElButton><ElButton @click="startCreate('task')">新建任务</ElButton><ElButton @click="startCreate('issue')">登记 Issue</ElButton><ElButton @click="startCreate('release')">创建发布记录</ElButton></div>
    <ElCard class="delivery-releases"><h2>发布记录</h2><template v-if="releases.length"><button v-for="item in releases" :key="item.id" @click="choose(item)">{{ item.id }} · {{ item.title }} · {{ statuses[item.status] }}</button></template><p v-else>当前没有发布记录；正式发布须通过审核、Issue、测试与回滚检查。</p></ElCard>
    <ElCard v-if="selected" class="delivery-detail" tabindex="-1"><div class="delivery-detail-head"><div><small>{{ selected.id }} · {{ selected.priority }} · {{ statuses[selected.status] }}</small><h2>{{ selected.title }}</h2></div><div class="delivery-actions"><ElButton v-if="selected.kind === 'requirement'" :disabled="selected.status === 'approved' && role !== 'productOwner'" @click="startEditRequirement(selected)">编辑需求范围</ElButton><ElButton @click="selectedId = ''">关闭详情</ElButton></div></div><p>{{ selected.description }}</p><dl><dt>阶段</dt><dd>{{ selected.phase }}</dd><dt>负责人</dt><dd>{{ selected.owner }}</dd><dt>风险</dt><dd>{{ selected.risk || '未记录' }}</dd><dt>关联需求</dt><dd>{{ selected.requirementIds.join('、') || '未关联' }}</dd></dl><h3>追溯链</h3><div v-if="related.length" class="delivery-related"><button v-for="item in related" :key="item.id" @click="choose(item)">{{ item.id }} · {{ item.title }} · {{ statuses[item.status] }}</button></div><p v-else>尚无关联记录。</p>
      <div v-if="selected.kind === 'requirement'" class="delivery-inline"><label>需求状态<select v-model="statusDraft" aria-label="需求状态"><option value="draft">草案</option><option value="pending">待审核</option><option value="inProgress">进行中</option><option value="approved">已批准</option></select></label><ElButton type="primary" @click="saveStatus">保存需求状态</ElButton></div>
      <div v-if="selected.kind === 'task' || selected.kind === 'issue'" class="delivery-inline"><label>状态<select v-model="statusDraft" aria-label="编辑记录状态"><option v-for="(label,id) in statuses" :key="id" :value="id">{{ label }}</option></select></label><label v-if="isIssue(selected)">处理结论<input v-model="resolution" aria-label="Issue 处理结论"></label><ElButton type="primary" @click="saveStatus">保存状态</ElButton></div>
      <div v-if="isReview(selected)" class="delivery-inline"><p>指定审核人：{{ selected.reviewerId }}。以下仅记录当前浏览器的模拟结论。</p><label>审核结论<select v-model="reviewVerdict" aria-label="审核结论"><option value="needsChanges">需修改</option><option value="approved">通过</option><option value="rejected">驳回</option><option value="waived">豁免</option></select></label><label>审核原因<textarea v-model="reviewReason" aria-label="审核原因"></textarea></label><ElButton type="primary" @click="decide">记录模拟审核结论</ElButton></div>
      <div v-if="isRelease(selected)" class="delivery-inline"><p>环境：{{ selected.environment }} · 版本：{{ selected.version }} · 上一版本：{{ selected.previousVersion || '缺失' }}</p><ElButton :disabled="role !== 'releaseLead' || selected.status === 'done' || !!selected.rollback" @click="startEditRelease(selected)">补齐发布材料</ElButton><ElButton type="primary" :disabled="role !== 'releaseLead' || !delivery.checkRelease(selected).ready" @click="publish">标记模拟发布</ElButton></div>
      <div v-if="isRelease(selected)" class="delivery-check"><strong>当前发布清单</strong><section v-for="group in [{ name: '通过', items: delivery.checkRelease(selected).passed }, { name: '警告', items: delivery.checkRelease(selected).warnings }, { name: '阻塞', items: delivery.checkRelease(selected).blocked }]" :key="group.name" class="delivery-check-group" :aria-label="`${group.name}检查项`"><h3>{{ group.name }}（{{ group.items.length }}）</h3><ul><li v-for="item in group.items" :key="item">{{ item }}</li></ul></section></div>
      <div v-if="isRelease(selected) && selected.status === 'done'" class="delivery-inline"><p>仅记录模拟回滚到上一已验证版本；不执行部署。</p><label>回滚原因<input v-model="rollbackReason" aria-label="回滚原因"></label><label>回滚复验结果<input v-model="rollbackVerification" aria-label="回滚复验结果"></label><ElButton type="primary" :disabled="role !== 'releaseLead'" @click="rollback">记录模拟回滚</ElButton></div>
      <p v-if="isRelease(selected) && selected.rollback">模拟回滚：{{ selected.rollback.toVersion }} · {{ selected.rollback.reason }} · {{ selected.rollback.verification }}</p>
      <h3>不可覆盖的修订记录</h3><ol><li v-for="item in selected.history" :key="`${item.revision}_${item.action}`">第 {{ item.revision }} 版 · {{ item.action }} · {{ item.actorId }}</li></ol></ElCard>
  </main>
  <div v-if="editor" class="delivery-backdrop"><section class="delivery-modal" role="dialog" aria-modal="true" :aria-label="`${editingRequirementId || editingReleaseId ? '编辑' : '新建'}${editor === 'requirement' ? '需求' : editor === 'task' ? '任务' : editor === 'issue' ? 'Issue' : '发布记录'}`"><div class="delivery-detail-head"><h2>{{ editingRequirementId || editingReleaseId ? '编辑' : '新建' }}{{ editor === 'requirement' ? '需求草案' : editor === 'task' ? '任务' : editor === 'issue' ? 'Issue' : '发布记录' }}</h2><button aria-label="关闭新建" @click="editor = null">×</button></div><div class="delivery-form"><label>标题<input :value="editor === 'release' ? releaseDraft.title : title" aria-label="交付标题" @input="editor === 'release' ? releaseDraft.title = ($event.target as HTMLInputElement).value : title = ($event.target as HTMLInputElement).value"></label><label v-if="editor === 'requirement'">需求编号<input v-model="newId" aria-label="需求编号" :readonly="!!editingRequirementId" placeholder="IOT-EXAMPLE-001"></label><label v-if="editor !== 'requirement' && editor !== 'release'">关联需求<select v-model="requirementId" aria-label="新记录关联需求"><option value="">未关联</option><option v-for="item in requirements" :key="item.id">{{ item.id }}</option></select></label><template v-if="editor !== 'release'"><label>负责人<input v-model="owner" aria-label="交付负责人"></label><label>优先级<select v-model="priority" aria-label="新记录优先级"><option v-for="item in ['P0','P1','P2','P3']" :key="item">{{ item }}</option></select></label><label class="wide">说明<textarea v-model="description" aria-label="交付说明"></textarea></label></template><label v-if="editor === 'requirement'" class="wide">验收标准（每行一项）<textarea v-model="acceptance" aria-label="验收标准"></textarea></label><label v-if="editor === 'issue'">严重度<select v-model="severity" aria-label="Issue 严重度"><option value="critical">严重</option><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></label>
      <template v-if="editor === 'release'"><label>环境<select v-model="releaseDraft.environment" aria-label="发布环境"><option value="local">本地</option><option value="preview">预览</option><option value="production">正式</option></select></label><label>版本<input v-model="releaseDraft.version" aria-label="目标版本"></label><label>上一已验证版本<input v-model="releaseDraft.previousVersion" aria-label="上一已验证版本"></label><label>关联需求<select :value="releaseDraft.requirementIds[0] ?? ''" aria-label="发布关联需求" @change="releaseDraft.requirementIds = ($event.target as HTMLSelectElement).value ? [($event.target as HTMLSelectElement).value] : []"><option value="">请选择</option><option v-for="item in requirements" :key="item.id">{{ item.id }}</option></select></label><label class="wide">变更摘要<textarea v-model="releaseDraft.changeSummary" aria-label="变更摘要"></textarea></label><label class="wide">构建与测试证据（每行一个引用）<textarea :value="releaseDraft.testEvidence.join('\n')" aria-label="测试证据" @input="releaseDraft.testEvidence = ($event.target as HTMLTextAreaElement).value.split('\n').map(item => item.trim()).filter(Boolean)"></textarea></label><label class="wide">回滚步骤<textarea v-model="releaseDraft.rollbackSteps" aria-label="回滚步骤"></textarea></label><div class="wide delivery-check"><strong>{{ releaseCheck.ready ? '清单就绪（仅本地模拟）' : '清单阻塞' }}</strong><section v-for="group in [{ name: '通过', items: releaseCheck.passed }, { name: '警告', items: releaseCheck.warnings }, { name: '阻塞', items: releaseCheck.blocked }]" :key="group.name" class="delivery-check-group" :aria-label="`${group.name}检查项`"><h3>{{ group.name }}（{{ group.items.length }}）</h3><ul v-if="group.items.length"><li v-for="item in group.items" :key="item"><span>{{ item }}</span><template v-if="group.name !== '通过'"><small>下一责任人：{{ releaseAction(item).owner }}</small><button v-if="releaseAction(item).target" type="button" :aria-label="`查看缺失材料：${item}`" @click="openReleaseAction(item)">查看材料</button></template></li></ul><p v-else>无</p></section></div></template>
    </div><div class="delivery-actions"><ElButton type="primary" @click="saveNew">保存模拟记录</ElButton><ElButton @click="editor = null">取消</ElButton></div><p v-if="message" role="alert">{{ message }}</p></section></div>
</div>
</template>
